GimCorpus.put(464,0,[[3,1,"אלמנה בין שהיא עניה בין שהיא וכו' עד שנאמר ולא תחבול בגד אלמנה. א\"א בשעת הלואה אין זה חובל עכ\"ל:",1,0],[3,2,"וכן המלוה את חבירו וכו' עד כי נפש הוא חובל. א\"א לא נהיר עכ\"ל:",1,0],[3,3,"כשם שהרכב והרחים וכו' עד לוקה שתים. א\"א זה אינו עכ\"ל:",1,0],[3,4,"עבר בעל חוב ונכנס עד כבוא השמש. א\"א שבוש הוא זה אלא מפני שנתחייב באחריותו כדכתיבנא לעיל עכ\"ל:",1,0],[3,6,"שליח ב\"ד שבא למשכן וכו' עד הלילה בלילה. א\"א זה אינו מחוור שהרי פסק למעלה שאפי' שליח ב\"ד שבא למשכן לא יכנס כו' והלוה מוציא לו המשכון א\"ו ראוי לומר אעפ\"כ בגד שעליו וכלים שאוכל בהם כגון קערה ושלחן ומפה שהוא צריך להם לאכילת היום והלילה לא יטול כלל וכן מטה ומצע ומפץ שהן צריכין ביום ובלילה ושלא בשעת סדור קאמר עכ\"ל:",1,0],[3,6,"היו לפניו שני כלים עד שלשים יום. א\"א כמ\"ש סתם הלואה שלשים יום עכ\"ל:",2,0],[4,13,"הורו מקצת הגאונים וכו', יראה לי שאין הוראה זו נכונה. א\"א, הורו מקצת הגאונים וכו' ולפיכך אין המחילה מועלת ברבית אפלו ברבית של דבריהם. א\"א חיי ראשי הוראת הגאונים נכונה היא, אם כן מלוי בריבית יעשו כן להתיר להם הריבית, והגזלנין ומלוי בריבית שהחזירו בדרך תשובה, אין מקבלים מהן כדי להדריכם בתשובה.",1,0],[5,1,"ומצות עשה להשיך וכו' עד וזהו דין תורה. א\"א אני לא מצאתי שמועה זו ואולי טעה במה שמצא בספרי (פרשת כי תצא) שנאמר שם לנכרי תשיך זו מצות עשה ופירושו משום דהוה ליה לאו הבא מכלל עשה שלא ישיך לישראל עכ\"ל:",1,0],[6,2,"לפיכך אם לא החזיר חובו וכו' עד ואינה יוצאה בדיינים. א\"א אין כאן מקום לשודא דדייני ואולי ר\"ל מנכה לו כמנהג נכיית המקום ולא נהיר שאם לא הורידו הוא לדירה אין כאן סילוק דהא ליכא תפיסה ולא עוד אלא שיכול לתבוע בדין כל שכר החצר כדין כל הדר בחצר חבירו בסתם שהוא מעלה לו שכר הרגיל לו ואם לא תבעו ופרע לו את חובו משלם כבר נתן לו רבית מאוחרת ושניהם באיסור וזה דרך אמת עכ\"ל:",1,0],[6,3,"הורו רבותי שהמלוה את חבירו עד שנאמר לא תתן לו בנשך. א\"א חיי ראשי לא יפה הורו שאם הגיע זמן הפרעון וארווח ליה זמניה משום ההוא דירה כשעת מתן מעות דמיא וקידושין יוכיחו עכ\"ל:",1,0],[6,4,"המלוה את חבירו על השדה ואמר לו עד מפני שהוא רבית של תורה. א\"א אין הדעת מקבלת שיהא זה רבית קצוצה אלא כי אמר ר\"נ הדרא ארעא והדרי פירי דינא קאמר דאיהו לא יהיב ליה מידי ורבה בר רב הונא הוה ס\"ל אע\"ג דמדינא הדרא אי תפיס להו כאבק רבית דמי ולא מפקינן מיניה ורבינא דחשיב ואפיק להו לאו משום רבית אלא משום גזילה אבל אי מחל להו והדר תבעינהו תו לא הדרי דרבית מאוחרת היא ותו לא קשיא מידי דרבינא אדרבינא עכ\"ל:",1,0],[6,7,"הורו רבותי שהמלוה את חבירו וכו' עד כמו שהורו רבותי. א\"א אמת הוא זה שהחמירו בכרם יותר משדה ולא להקל במשכונא שדה אלא להחמיר במכירת כרם אבל מי שסובר במשכנתא בלא נכייתא שהוא רבית קצוצה אמר כן אף בשדה ומאי דקשיא להו דרבינא אדרבינא הא איתרצא לה כדכתיבנא לעיל ועוד יש לנו הפלגות כי יש חילוק בין אתרא דמסלקי לאתרא דלא מסלקי והן מפורשות אצלנו. עכ\"ל:",1,0],[6,8,"וכן אם התנה בעל השדה וכו' עד ה\"ז מותר. א\"א טעה בדבריהם ומה בין זה למשכנתא בנכייתא וכי יש הפרש בין נכייתא רבה לנכייתא זוטא ואותם הגאונים המחמירים לא התירו אלא הראשון בלבד והיא משכנתא דסורא עכ\"ל:",1,0],[7,7,"הממשכן ביתו כו' עד הרי זה מותר. א\"א קשיא לי והא אסמכתא היא דהא לא ידע אי מזבין לה או לא ואימת קני לה ומסתברא בדאמר ליה מעכשיו ואפילו הכי בדמים הללו אסור הואיל ולא פסיקא מילתא דזביני עכ\"ל:",1,0],[8,5,"אסור לקנות פרי הפרדס כו' אבל אם קנה עגל עד דבר מצוי. א\"א זה פירוש בתורי דנפיש פסידייהו ואיננו נכון עכ\"ל:",1,0],[9,8,"החמריןשנכנסולעיר וכו'עדומסעדיןאותו. א\"א לא נהיר ולא צהירעכ\"ל:",1,0],[10,1,"כשם שמותר למוכר וכו' אע\"פ שיש לו כו' ה\"ז אסור וכו' עד באיזה זמן שיפרע. א\"א חדוש זה לא שמענו מעולם אלא אם יש לו או על שער שבשוק לוה סאה בסאה סתם בלא עשיית דמים אפילו לזמן קצוב עכ\"ל:",1,0],[11,1,"לפיכך האומר היו עלי עדים וכו' עד ביד המלוה. א\"א אני קבלתי שלא נאמר בגמרא אלא בכותב כתובה לאשתו ומוסיף לה אבל בהודאות והלואות לא צריך לאימלוכי ביה עכ\"ל:",1,0],[12,1,"אין נפרעין מן היורשין וכו' עד את השטר. א\"א הרב ז\"ל אומר שאם האמינו עליו ועל יורשיו שמועיל בו נאמנות ואם כתב בו שיהא נאמן אפילו על שובר ואפילו על מאה עדים למה אינו גובה אלא לפי הקושיות שהקשו על רב אשי במס' ערכין ולא תירצו זה התירוץ בשטר שיש בו נאמנות ש\"מ אין שום נאמנות מועיל לקטנים עכ\"ל:",1,0],[12,4,"הורו מקצת הגאונים וכו' עד שנזקקין להן שלא חשו לחן האשה. א\"א הם לא חשו ומרימר דהוא בתרא וכן עולא חששו עכ\"ל:",1,0],[13,3,"מלוה שבא לב\"ד וכו' עד מה שטען. א\"א יש כאן שבושין עכ\"ל:",1,0],[13,4,"אבל אם אמר המלוה אני יודע וכו' עד על מי שטען שקר. א\"א על שיטתו הוא הולך ואין אנו נסכמים עמו לפי שלא בא איני יודע של זה על ברי של זה שאינו אומר אתה יודע ששנים היה שוה אבל ודאי אם אמר לו כן הדין כדבריו עכ\"ל:",1,0],[14,3,"הוציא עליו שטר מקויים עד זה מחלוקת בין הגאונים יש מי שהורה וכו' ורבותי הורו וכו' עד ולזה דעתי נוטה. א\"א הרב ז\"ל כתב זה בתשובה והיתה השאלה שטען הלוה [שיש בשטר] העלאה לזמן ואפשר שלא אמר הרב ז\"ל אלא על אותה הטענה בלבד לפי שבני אדם מתפרצין בזה וסומכים על מה שראו דמר אמר טרשא שרי ומר אמר טרשא דידי ודאי שרי אבל על שאר הטענות לא אמר הרב ויש דמות ראיה לזה כי הפוגמת כתובתה נשבעת והפוחתת נוטלת בלא שבועה לפי שהשטר מצוי יותר בפרעון עכ\"ל:",1,0],[14,11,"וכן הורו רבותי וכו' עד ומשלם וכו'. א\"א אני אפרש מכיון שאמר בתחלה לא לויתי כאילו אמר לא פרעתי ואילו לא חזר והודה היה נשבע להכחיש את העד ועכשיו שחזר והודה לעד שלוה שוב אינו יכול לחזור ולהכחיש ולומר שפרע שהרי הודה לו בראשונה שלא פרע ואילו לא הכחישו העד בתחלה לא היינו אומרים כבר הודה שלא פרע הואיל ויכול לעמוד בטענתו בלא שבועה ועכשיו שנתחייב שבועה הוה ליה מחוייב שבועה שאינו יכול לישבע שכבר חזר והודה לעדות הראשונה שלוה ולא פרע כמו שאמר העד:",1,0],[14,13,"מישהיה לו וכו' עד ולפיכך וכו'. א\"א אין דין זה מחוור ומלובן דאם איתא דאפילו באבד כל תוך זמנו לא חיישינן לפריעה מה טעם לא מהדרינן ליה כשנפל דאמרינן בהדיא פ\"ק דמציעא דאפילו כתוב בו ביום לא מהדרינן ליה אלא ודאי כל דנפל איתרע ליה וכל שכן אבד דאיתרע ליה ורגלים לדבר דבשבועה מיהא יטול עכ\"ל:",1,0],[14,13,"וכן הורו רבותי וכו' עד אין שם חזקה. א\"א ואף זה לא נהיר ולא בהיר ולא צהיר עכ\"ל:",2,0],[15,1,"המלוה את חבירו וכו' ועוד אם מתו מה יעשה וכו' אבל ודאי וכו' עד וכזה ראוי לדון ולהורות. א\"א אמת הוא שהנוסחאות מתחלפות בזה ואני קיימתי את שתיהן שאם יש עדים על התנאי שאמר לו אל תפרעני אלא בעדים ואמר פרעתי והלכו להם אינו נאמן ואם אין שם עדים נאמן מגו דיכול לומר לא התנה עמי אבל כשאמר לא תפרעני אלא בפני פלוני ופלוני באמת נראין דברי הרב ז\"ל דאמר פסלינהו לכ\"ע לגבי האי פרעון וכי אתו אחריני ואמרי קמן פרעיה מצי אמר סטראי נינהו והתימה שתמה זה החכם על זה ואמר שאפילו אמר בפני פלוני ופלוני אם יבואו עדים שפרעו בפניהם אין כאן בית מיחוש ותמה על מה שאמרו מהימנת עלי כבי תרי שיפרע לו פעם אחר פעם אלא אם יש לו שטר יקרע שטרו ואם אין לו שטר יכתוב לו שטר שובר בכתב ידו וזו היא תקנתו לכל ענין עכ\"ל:",1,0],[15,7,"התנה המלוה שיהיה גובה וכו' עד לאבד ממון חבירו. א\"א אלו הם דברי הרב ז\"ל ולא הסכמנו עמו ויש לנו ראיות גדולות לדברינו שמאחר שהם לקחו ממנו אחר התנאי אינהו הוא דאפסידו אנפשייהו:",1,0],[16,2,"היה ראובן חייב לשמעון מנה וכו' עד שיגיע ליד שמעון כל חובו. א\"א אחריות לוי השליח איני יודע מה הוא אלא שאם יכפור ראובן במלוה נמצא לוי פושע בדבר עכ\"ל:",1,0],[18,4,"עשה שדהו אפותיקי לבעל חובו וכו' עד אבל אם מכרה ממכר עולם אינה מכורה. א\"א לא הבחין ולא הבין דרך הירושלמי אשר מצא על זאת המימרא:",1,0],[18,6,"עבד שעשאהו רבו אפותיקי וכו'. א\"א הוא פוסק כרבן שמעון בן גמליאל והרב לא פסק כן עכ\"ל:",1,0],[19,8,"מכר הלוה שדה ללוקח וכו' עד וכן האשה בכתובתה. א\"א זה הפירוש למה שאמרו וכן ב\"ח ושני לקוחות ובחיי ראשי לא ראיתי בכל ספריו טעות גדולה כזו מכמה תשובות האחד שאין זו החלילה אלא כשמכר הלוקח ראשון לשני באחריות ומשנתנו אין בו הפלגה וקאמר וכן ב\"ח, והב' משנתנו הפשרה מתחלה לשלשתן וכאן אין הפשרה אלא לשני ב\"ח וא' מן הלקוחות שהרי אחד מן הלקוחות קיבל מעותיו, והג' שאף לב' אין כאן פשרה כי כשיטרוף ב\"ח השדה מלוקח שני הלך אצל לוקח ראשון ולקח מעותיו כשיבא לוקח ראשון ויוציא השדה מב\"ח אותו ב\"ח על מי יחזור והלוקח שני כבר לקח מעותיו והלך לו נמצא הוא לבדו מפסיד, והרביעית שאף לכתחלה אין ב\"ח יכול לטרוף מלוקח שני משום דאמר ליה אי שתקת שתקת ואי לא מהדרנא שטרא למריה וכן הדין למי שאבדה לו דרך שדהו. ועל זה הדרך חולקין אפילו הן מאה כשיצאו לגבות כאחת עכ\"ל:",1,0],[20,3,"שטרות שזמן כולן וכו'. א\"א מאין הוציא זה דין חדש לומר כל הקודם זכה במה שאמרו חכמים יחלוקו ולא לשתמיט תנא בחד דוכתא ולימא יחלוקו או כל הקודם זכה ואין לנו אלא מה שמנו חכמים וחוץ מזה משפט מעוקל עכ\"ל:",1,0],[20,4,"ועל דרך זה חולקים וכו'. א\"א זהו כפירוש הרב לדעת רבינו עכ\"ל:",1,0],[21,3,"מתנה ששבחה מחמת וכו' עד גובה את כולה. א\"א דעת יחיד הוא זה והרב ז\"ל אמר כן במסתברא וראוי לסמוך עליו עכ\"ל:",1,0],[21,4,"וכן יתומים וכו' עד מן השבח כלום. א\"א גם זו דעת יחיד היא ויש לנו דרך אחרת ביתומים אומרים אנו השבחנו עכ\"ל:",1,0],[21,6,"היתה השדה אפותיקי וכו' עד מן המוכר. א\"א לא ידעתי מהו כי חצי השבח הראוי ללוקח ההוצאה ג\"כ תהיה חצי ההוצאה משלו ואם ישאר חצי השבח לפניו והרי הכל שלו אין לו ליטול הוצאה מאדם ואם יטול ב\"ח את הכל יפרע כל דמי חצי השבח ללוקח וההוצאה נכללת בו שהרי השבח יתר על ההוצאה וחצי השבח הראוי לב\"ח נותן את חצי ההוצאה ללוקח ונוטל הלוקח מן המוכר ולא מבעל חוב דאמר ליה ארעא דידי אשבחא ואי אפשר בלא טעות סופר עכ\"ל:",1,0],[22,15,"בית דין ששמו לטורף וכו' עד כזה הורו. א\"א אפשר בשלא הכריזו קאמרי עכ\"ל:",1,0],[23,11,"בשטרי החובות וכו' עד כמו שיתבאר. א\"א זהו תימה מאחר שהוא תוך זמן למה לא יגבה ויכתוב שובר עכ\"ל:",1,0],[23,12,"מי שבלה וכו' עד שתתקיים עדותן. א\"א איני יודע מהו עדים הראשונים ומה יהיה קיום עדותן אבל צריך להביא ראיה שנחקרו העדים ונמצא עדותן מכוונת על מה שראו בשטר עכ\"ל:",1,0],[24,7,"ראש ב\"ד שהיה יודע וכו' עד מלה מלה. א\"א שטר מעשה ב\"ד עכ\"ל:",1,0],[25,4,"התנה המלוה עם הערב וכו' עד שיש נכסים ללוה. א\"א שבוש הוא שאע\"פ שאמר על מנת שאפרע ממי שארצה תחלה אם יש נכסים ללוה לא יפרע מן הערב עכ\"ל:",1,0],[25,5,"אבל אם אמר לו הלוהו ואני וכו' עד ממי שארצה אפרע. א\"א אף זה שבוש עכ\"ל:",1,0],[25,6,"ערב של כתובה וכו' עד וקבלן של כתובה חייב. א\"א כי האב אע\"פ שלא קנו מידו עכ\"ל:",1,0],[25,7,"ראובן שמכר לשמעון וכו' עד וכזה הורו רבותי. א\"א שבוש הוא זה שאם אמר בשעת מתן מעות משתעבד ואין בערבות משום אסמכתא עכ\"ל:",1,0],[25,10,"שנים שערבו לאחד עד בשאר החוב. א\"א אינו מחוור אלא לפי המנהג ולמדין מן העכו\"ם לישראל עכ\"ל:",1,0],[25,13,"מי שלא פירש וכו' עד ודברים של טעם וכו'. א\"א וא\"כ לא ברב ולא במעט אלא כדי שהדעת מגעת לשם שהוא רגיל ואמיד נשתעבד עכ\"ל:",1,0],[25,14,"מי שאמר לחבירו הלוהו ואני ערב לגופו של וכו' עד ולזה דעתי נוטה. א\"א דל אסמכתא מהכא שהרי סלקו אותה בגמרא אלא אם אמר בשעת מתן מעות הלוהו ואני ערב לך להביא בידך את גופו ואם לא אוכל להשיבו אשלם לית דין ולית דיין שהוא חייב לשלם ואם לא אמר לו כך למה יתחייב ממון אלא י\"ל שיבא גוף תחת גוף עד שיתפשר עמו עכ\"ל:",1,0],[26,6,"בד\"א וכו' עד חייב לשלם לו כלום. א\"א אלו דברים שאין הדעת מקבלתן ואין השכל סובלן עכ\"ל:",1,0],[27,1,"והורו רבותי וכו' עד איני מודה בזה. א\"א יפה הורו רבותיו שאפילו היה שט\"ח שלהן וכו' שהשטר העולה בערכאות שלהן וחותמיהן עכו\"ם אינו גובה ממשועבדים דלית להו קלא הילכך אפשר שנפרע ולא תבעו עכ\"ל:",1,0],[27,16,"שטר שכתוב בו אסתירא וכו' עד בדבר שאין בו ספק. א\"א זה שבוש ואינו נוטל אלא אסתירא עכ\"ל:",1,0]]);
